CREATE SCHEMA IF NOT EXISTS bestie;
SET LOCAL search_path=bestie,public;
CREATE TABLE player_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_user_id text NOT NULL UNIQUE,username text UNIQUE NOT NULL CHECK(username ~ '^[a-z0-9_]{3,24}$'),display_name varchar(40) NOT NULL,avatar_object_key text,character_id text NOT NULL DEFAULT 'Bunny',character_color text NOT NULL DEFAULT '#ff99af',bio varchar(280) NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE player_settings(user_id uuid PRIMARY KEY REFERENCES player_profiles ON DELETE CASCADE,music_enabled boolean NOT NULL DEFAULT false,sound_enabled boolean NOT NULL DEFAULT false,music_volume real NOT NULL DEFAULT .65 CHECK(music_volume BETWEEN 0 AND 1),sound_volume real NOT NULL DEFAULT .65 CHECK(sound_volume BETWEEN 0 AND 1),reduced_motion boolean NOT NULL DEFAULT false,preferred_controls text NOT NULL DEFAULT 'auto' CHECK(preferred_controls IN ('auto','touch','keyboard')),public_leaderboard boolean NOT NULL DEFAULT false,updated_at timestamptz DEFAULT now());
CREATE TABLE game_worlds(id int PRIMARY KEY,slug text UNIQUE NOT NULL,name text NOT NULL,description text NOT NULL,world_number int UNIQUE NOT NULL,thumbnail text NOT NULL,background_asset text NOT NULL,difficulty int NOT NULL,is_active boolean DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE game_levels(id int PRIMARY KEY,world_id int NOT NULL REFERENCES game_worlds,slug text UNIQUE NOT NULL,level_number int UNIQUE NOT NULL CHECK(level_number BETWEEN 1 AND 36),title text NOT NULL,description text NOT NULL,objective text NOT NULL,difficulty int NOT NULL,mechanic_type text NOT NULL,level_config jsonb NOT NULL,star_thresholds jsonb NOT NULL,prerequisites jsonb NOT NULL,content_version int NOT NULL,is_active boolean DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE game_sessions(id uuid PRIMARY KEY,session_id uuid UNIQUE NOT NULL,room_code_hash text NOT NULL,host_user_id uuid REFERENCES player_profiles ON DELETE SET NULL,status text NOT NULL,started_at timestamptz NOT NULL,ended_at timestamptz,total_duration int DEFAULT 0,created_at timestamptz DEFAULT now());
CREATE TABLE game_session_players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES game_sessions,user_id uuid REFERENCES player_profiles ON DELETE SET NULL,guest_player_id text NOT NULL,player_role int NOT NULL,character_id text NOT NULL,joined_at timestamptz DEFAULT now(),left_at timestamptz,UNIQUE(session_id,guest_player_id));
CREATE INDEX session_player_lookup ON game_session_players(user_id,session_id);
CREATE TABLE level_attempts(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES game_sessions,level_id int NOT NULL REFERENCES game_levels,attempt_number int NOT NULL,outcome text NOT NULL CHECK(outcome IN ('win','loss','abandoned')),duration_ms int NOT NULL CHECK(duration_ms>=0),mistakes int NOT NULL CHECK(mistakes>=0),teamwork_score int NOT NULL CHECK(teamwork_score BETWEEN 0 AND 100),stars_earned int NOT NULL CHECK(stars_earned BETWEEN 0 AND 3),created_at timestamptz DEFAULT now(),UNIQUE(session_id,attempt_number));
CREATE TABLE level_attempt_players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES level_attempts,user_id uuid REFERENCES player_profiles ON DELETE CASCADE,player_character text NOT NULL,individual_score int NOT NULL,participation_status text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(attempt_id,user_id));
CREATE TABLE player_level_progress(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES player_profiles ON DELETE CASCADE,level_id int NOT NULL REFERENCES game_levels,status text NOT NULL,attempts_count int NOT NULL DEFAULT 0,completion_count int NOT NULL DEFAULT 0,best_time_ms int,best_teamwork_score int NOT NULL DEFAULT 0,best_stars int NOT NULL DEFAULT 0,first_completed_at timestamptz,last_played_at timestamptz,updated_at timestamptz DEFAULT now(),UNIQUE(user_id,level_id));
CREATE TABLE player_stats(user_id uuid PRIMARY KEY REFERENCES player_profiles ON DELETE CASCADE,total_xp int NOT NULL DEFAULT 0,total_stars int NOT NULL DEFAULT 0,levels_completed int NOT NULL DEFAULT 0,total_playtime_seconds int NOT NULL DEFAULT 0,total_games int NOT NULL DEFAULT 0,best_teamwork_score int NOT NULL DEFAULT 0,updated_at timestamptz DEFAULT now());
CREATE TABLE achievements(id int PRIMARY KEY,slug text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL,category text NOT NULL,icon text NOT NULL,unlock_condition jsonb NOT NULL);
CREATE TABLE player_achievements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES player_profiles ON DELETE CASCADE,achievement_id int NOT NULL REFERENCES achievements,unlocked_at timestamptz DEFAULT now(),UNIQUE(user_id,achievement_id));
CREATE TABLE player_inventory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES player_profiles ON DELETE CASCADE,cosmetic_id text NOT NULL,acquired_at timestamptz DEFAULT now(),source text NOT NULL,is_equipped boolean NOT NULL DEFAULT false,UNIQUE(user_id,cosmetic_id));
CREATE TABLE consumed_tickets(jti uuid PRIMARY KEY,expires_at timestamptz NOT NULL);
CREATE INDEX ticket_expiry ON consumed_tickets(expires_at);
CREATE TABLE avatar_uploads(key text PRIMARY KEY,user_id uuid NOT NULL REFERENCES player_profiles ON DELETE CASCADE,mime text NOT NULL,bytes int NOT NULL CHECK(bytes BETWEEN 1 AND 2097152),expires_at timestamptz NOT NULL);
